import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { FiArrowRight, FiBriefcase, FiLogOut, FiMapPin, FiUser } from 'react-icons/fi';
import BrandMark from '../components/common/BrandMark';
import EmptyState from '../components/common/EmptyState';
import ErrorMessage from '../components/common/ErrorMessage';
import LoadingSpinner from '../components/common/LoadingSpinner';
import { useAuth } from '../hooks/useAuth';
import { getClientSites, getClientProfile } from '../services/siteService';

const SiteSelection = () => {
  const [sites, setSites] = useState([]);
  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  const load = async () => {
    setLoading(true);
    try {
      // ✅ Fetch both sites and profile
      const [sitesData, profileData] = await Promise.all([
        getClientSites(),
        getClientProfile()
      ]);
      setSites(sitesData.sites || []);
      setProfile(profileData.client || null);
      setError('');
    } catch (err) {
      setError(err.response?.data?.error || 'Unable to load project sites.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, []);

  if (loading) return (
    <div className="portal-page grid place-items-center min-h-screen">
      <LoadingSpinner message="Loading your projects…" />
    </div>
  );

  if (error) return (
    <div className="portal-page grid place-items-center min-h-screen">
      <ErrorMessage message={error} onRetry={load} />
    </div>
  );

  return (
    <div className="portal-page min-h-screen">
      <div className="portal-shell selection-shell h-screen max-h-screen overflow-hidden">

        {/* ========== SIDEBAR ========== */}
        <aside className="portal-sidebar selection-sidebar h-full flex flex-col py-4 px-3">
          <div className="flex items-center gap-2 px-2 mb-2">
            <BrandMark />
            <div className="text-xs">
              <div className="font-bold text-textPrimary">Aeroview 360</div>
              <div className="text-[10px] text-textMuted -mt-0.5">Client Portal</div>
            </div>
          </div>

          <div className="portal-rule my-2" />

          {/* Client Company */}
          <div className="flex items-center gap-3 px-2 py-2 bg-gray-50 rounded-lg">
            {profile?.company_logo ? (
              <img
                src={profile.company_logo}
                alt={profile.client_name}
                className="w-10 h-10 rounded-lg object-cover border border-gray-200 flex-shrink-0"
              />
            ) : (
              <div className="w-10 h-10 rounded-lg bg-primaryDark text-white flex items-center justify-center font-bold text-sm flex-shrink-0">
                {profile?.client_name?.slice(0, 2).toUpperCase() || 'C'}
              </div>
            )}
            <div className="min-w-0 flex-1">
              <div className="font-semibold text-sm text-textPrimary truncate">
                {profile?.client_name || user?.client_name || 'Client'}
              </div>
              <div className="text-[10px] text-textMuted uppercase tracking-wider">Client Workspace</div>
            </div>
          </div>

          <div className="portal-rule my-2" />

          {/* Features */}
          <div className="px-2 space-y-1 text-xs text-textSecondary">
            <p className="flex items-center gap-2"><FiBriefcase /> Project progress records</p>
            <p className="flex items-center gap-2"><FiMapPin /> Site-specific access</p>
          </div>

          <div className="portal-rule my-2" />

          {/* User & Logout */}
          <div className="mt-auto px-2">
            <div className="text-[10px] text-textMuted uppercase tracking-wider mb-1">Signed in as</div>
            <div className="font-medium text-sm text-textPrimary truncate">{user?.name}</div>
            <button
              onClick={() => { logout(); navigate('/login'); }}
              className="mt-2 flex items-center gap-1.5 text-xs text-textSecondary hover:text-red-600 transition-colors"
            >
              <FiLogOut size={14} />
              <span>Sign Out</span>
            </button>
          </div>
        </aside>

        {/* ========== MAIN CONTENT ========== */}
        <main className="portal-main selection-main h-full flex flex-col overflow-hidden p-4">

          {/* Header */}
          <div className="flex items-center gap-3 mb-4 flex-shrink-0">
            <div className="w-10 h-10 rounded-full bg-gray-100 flex items-center justify-center flex-shrink-0 overflow-hidden border border-gray-200">
              {profile?.company_logo ? (
                <img
                  src={profile.company_logo}
                  alt={profile.client_name}
                  className="w-full h-full object-cover"
                />
              ) : (
                <FiUser className="text-gray-400 text-lg" />
              )}
            </div>
            <div>
              <h1 className="text-lg font-bold text-textPrimary">Welcome Back!</h1>
              <p className="text-xs text-textSecondary">Select a site to access your dashboard</p>
            </div>
          </div>

          <div className="portal-rule mb-4 flex-shrink-0" />

          {/* Site List */}
          <div className="flex-1 overflow-y-auto pr-1">
            {sites.length === 0 ? (
              <EmptyState message="No project sites are available for your client account yet." />
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                {sites.map((site) => (
                  <button
                    key={site.site_id}
                    onClick={() => navigate(`/sites/${site.site_id}/360-tour`)}
                    className="flex items-center gap-3 p-4 bg-white rounded-xl border border-gray-200 hover:border-primaryDark hover:shadow-md transition-all text-left group"
                  >
                    <div className="w-10 h-10 rounded-lg bg-primaryDark/10 text-primaryDark flex items-center justify-center flex-shrink-0">
                      <FiBriefcase size={18} />
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="font-semibold text-sm text-textPrimary truncate">
                        {site.site_name || 'Unnamed Site'}
                      </div>
                      <div className="text-xs text-textSecondary truncate">
                        {site.location || 'Click to access dashboard'}
                      </div>
                      <div className="text-[10px] text-textMuted mt-0.5">
                        {site.status || 'Active'}
                      </div>
                    </div>
                    <FiArrowRight className="text-textMuted group-hover:text-primaryDark group-hover:translate-x-1 transition-all flex-shrink-0" />
                  </button>
                ))}
              </div>
            )}
          </div>

        </main>
      </div>
    </div>
  );
};

export default SiteSelection;
